+			    PROT_READ | PROT_WRITE),
+		   ENOMEM);
+	TEST_SUCC(mprotect(start_addr + PAGE_SIZE * 3, PAGE_SIZE,
+			   PROT_READ | PROT_WRITE));
+	TEST_RES(start_addr[PAGE_SIZE * 3] = 45,
+		 start_addr[PAGE_SIZE * 3] == 45);
+}
