+
+FN_TEST(msync)
+{
+	TEST_ERRNO(msync(start_addr + PAGE_SIZE, PAGE_SIZE * 3, 0), ENOMEM);
+	TEST_ERRNO(msync(start_addr + PAGE_SIZE * 2, PAGE_SIZE * 2, 0), ENOMEM);
+	TEST_SUCC(msync(start_addr + PAGE_SIZE * 3, PAGE_SIZE, 0));
