132: struct VmarInner {
133:     /// The mapped pages and associated metadata.
134:     ///
135:     /// When inserting a `VmMapping` into this set, use `insert_try_merge` to
136:     /// auto-merge adjacent and compatible mappings, or `insert_without_try_merge`
137:     /// if the mapping is known not mergeable with any neighboring mappings.
138:     vm_mappings: IntervalSet<Vaddr, VmMapping>,
139:     /// The total mapped memory in bytes.
140:     total_vm: usize,
141: }
142: 
143: impl VmarInner {
144:     const fn new() -> Self {
145:         Self {
146:             vm_mappings: IntervalSet::new(),
147:             total_vm: 0,
148:         }
149:     }
150: 
151:     /// Returns `Ok` if the calling process may expand its mapped
152:     /// memory by the passed size.
153:     fn check_extra_size_fits_rlimit(&self, expand_size: usize) -> Result<()> {
154:         let Some(process) = Process::current() else {
155:             // When building a `Process`, the kernel task needs to build
156:             // some `VmMapping`s, in which case this branch is reachable.
157:             return Ok(());
158:         };
159: 
160:         let rlimt_as = process
161:             .resource_limits()
162:             .get_rlimit(ResourceType::RLIMIT_AS)
163:             .get_cur();
164: 
165:         let new_total_vm = self
166:             .total_vm
167:             .checked_add(expand_size)
168:             .ok_or(Errno::ENOMEM)?;
169:         if new_total_vm > rlimt_as as usize {
170:             return_errno_with_message!(Errno::ENOMEM, "address space limit overflow");
171:         }
172:         Ok(())
173:     }
174: 
175:     /// Checks whether `addr..addr + size` is covered by a single `VmMapping`,
176:     /// and returns the address of the single `VmMapping` if successful.
177:     fn check_lies_in_single_mapping(&self, addr: Vaddr, size: usize) -> Result<Vaddr> {
178:         if let Some(vm_mapping) = self
179:             .vm_mappings
180:             .find_one(&addr)
181:             .filter(|vm_mapping| vm_mapping.map_end() - addr >= size)
182:         {
183:             Ok(vm_mapping.map_to_addr())
184:         } else {
185:             return_errno_with_message!(Errno::EFAULT, "the range must lie in a single mapping");
186:         }
187:     }
188: 
189:     /// Inserts a `VmMapping` into the `Vmar`, without attempting to merge with
190:     /// neighboring mappings.
191:     ///
192:     /// The caller must ensure that the given `VmMapping` is not mergeable with
193:     /// any neighboring mappings.
194:     ///
195:     /// Make sure the insertion doesn't exceed address space limit.
196:     fn insert_without_try_merge(&mut self, vm_mapping: VmMapping) {
197:         self.total_vm += vm_mapping.map_size();
198:         self.vm_mappings.insert(vm_mapping);
199:     }
200: 
201:     /// Inserts a `VmMapping` into the `Vmar`, and attempts to merge it with
202:     /// neighboring mappings.
203:     ///
204:     /// This method will try to merge the `VmMapping` with neighboring mappings
205:     /// that are adjacent and compatible, in order to reduce fragmentation.
206:     ///
207:     /// Make sure the insertion doesn't exceed address space limit.
208:     fn insert_try_merge(&mut self, vm_mapping: VmMapping) {
209:         self.total_vm += vm_mapping.map_size();
210:         let mut vm_mapping = vm_mapping;
211:         let addr = vm_mapping.map_to_addr();
212: 
213:         if let Some(prev) = self.vm_mappings.find_prev(&addr) {
214:             let (new_mapping, to_remove) = vm_mapping.try_merge_with(prev);
215:             vm_mapping = new_mapping;
216:             if let Some(addr) = to_remove {
217:                 self.vm_mappings.remove(&addr);
218:             }
219:         }
220: 
221:         if let Some(next) = self.vm_mappings.find_next(&addr) {
222:             let (new_mapping, to_remove) = vm_mapping.try_merge_with(next);
223:             vm_mapping = new_mapping;
224:             if let Some(addr) = to_remove {
225:                 self.vm_mappings.remove(&addr);
226:             }
227:         }
228: 
229:         self.vm_mappings.insert(vm_mapping);
230:     }
231: 
232:     /// Removes a `VmMapping` based on the provided key from the `Vmar`.
233:     fn remove(&mut self, key: &Vaddr) -> Option<VmMapping> {
234:         let vm_mapping = self.vm_mappings.remove(key)?;
235:         self.total_vm -= vm_mapping.map_size();
236:         Some(vm_mapping)
237:     }
238: 
239:     /// Finds a set of [`VmMapping`]s that intersect with the provided range.
240:     fn query(&self, range: &Range<Vaddr>) -> impl Iterator<Item = &VmMapping> {
241:         self.vm_mappings.find(range)
242:     }
243: 
244:     /// Calculates the total amount of overlap between `VmMapping`s
245:     /// and the provided range.
246:     fn count_overlap_size(&self, range: Range<Vaddr>) -> usize {
247:         let mut sum_overlap_size = 0;
248:         for vm_mapping in self.vm_mappings.find(&range) {
249:             let vm_mapping_range = vm_mapping.range();
250:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
251:             sum_overlap_size += intersected_range.end - intersected_range.start;
252:         }
253:         sum_overlap_size
254:     }
255: 
256:     /// Allocates a free region for mapping with a specific offset and size.
257:     ///
258:     /// If the provided range is already occupied, return an error.
259:     fn alloc_free_region_exact(&mut self, offset: Vaddr, size: usize) -> Result<Range<Vaddr>> {
260:         if self
261:             .vm_mappings
262:             .find(&(offset..offset + size))
263:             .next()
264:             .is_some()
265:         {
266:             return_errno_with_message!(
267:                 Errno::EEXIST,
268:                 "the range contains pages that are already mapped"
269:             );
270:         }
271: 
272:         Ok(offset..(offset + size))
273:     }
274: 
275:     /// Allocates a free region for mapping with a specific offset and size.
276:     ///
277:     /// If the provided range is already occupied, this function truncates all
278:     /// the mappings that intersect with the range.
279:     fn alloc_free_region_exact_truncate(
280:         &mut self,
281:         vm_space: &VmSpace,
282:         offset: Vaddr,
283:         size: usize,
284:         rss_delta: &mut RssDelta,
285:     ) -> Result<Range<Vaddr>> {
286:         let range = offset..offset + size;
287:         let mut mappings_to_remove = Vec::new();
288:         for vm_mapping in self.vm_mappings.find(&range) {
289:             mappings_to_remove.push(vm_mapping.map_to_addr());
290:         }
291: 
292:         for vm_mapping_addr in mappings_to_remove {
293:             let vm_mapping = self.remove(&vm_mapping_addr).unwrap();
294:             let vm_mapping_range = vm_mapping.range();
295:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
296: 
297:             let (left, taken, right) = vm_mapping.split_range(&intersected_range);
298:             if let Some(left) = left {
299:                 self.insert_without_try_merge(left);
300:             }
301:             if let Some(right) = right {
302:                 self.insert_without_try_merge(right);
303:             }
304: 
305:             rss_delta.add(taken.rss_type(), -(taken.unmap(vm_space) as isize));
306:         }
307: 
308:         Ok(offset..(offset + size))
309:     }
310: 
311:     /// Allocates a free region for mapping.
312:     ///
313:     /// If no such region is found, return an error.
314:     fn alloc_free_region(&mut self, size: usize, align: usize) -> Result<Range<Vaddr>> {
315:         // Fast path that there's still room to the end.
316:         let highest_occupied = self
317:             .vm_mappings
318:             .iter()
319:             .next_back()
320:             .map_or(VMAR_LOWEST_ADDR, |vm_mapping| vm_mapping.range().end);
321:         // FIXME: The up-align may overflow.
322:         let last_occupied_aligned = highest_occupied.align_up(align);
323:         if let Some(last) = last_occupied_aligned.checked_add(size)
324:             && last <= VMAR_CAP_ADDR
325:         {
326:             return Ok(last_occupied_aligned..last);
327:         }
328: 
329:         // Slow path that we need to search for a free region.
330:         // Here, we use a simple brute-force FIRST-FIT algorithm.

