27:         // FIXME: Linux returns `ENOMEM` if `(addr + len).align_up(PAGE_SIZE)` overflows. Here, we
28:         // perform a stricter validation.
29:         return_errno_with_message!(Errno::ENOMEM, "the mapping range is not in userspace");
30:     }
