201:     /// Inserts a `VmMapping` into the `Vmar`, and attempts to merge it with
202:     /// neighboring mappings.
203:     ///
204:     /// This method will try to merge the `VmMapping` with neighboring mappings
205:     /// that are adjacent and compatible, in order to reduce fragmentation.
206:     ///
207:     /// Make sure the insertion doesn't exceed address space limit.
208:     fn insert_try_merge(&mut self, vm_mapping: VmMapping) {
209:         self.total_vm += vm_mapping.map_size();
210:         let mut vm_mapping = vm_mapping;
211:         let addr = vm_mapping.map_to_addr();
212: 
213:         if let Some(prev) = self.vm_mappings.find_prev(&addr) {
214:             let (new_mapping, to_remove) = vm_mapping.try_merge_with(prev);
215:             vm_mapping = new_mapping;
216:             if let Some(addr) = to_remove {
217:                 self.vm_mappings.remove(&addr);
218:             }
219:         }
220: 
221:         if let Some(next) = self.vm_mappings.find_next(&addr) {
222:             let (new_mapping, to_remove) = vm_mapping.try_merge_with(next);
223:             vm_mapping = new_mapping;
224:             if let Some(addr) = to_remove {
225:                 self.vm_mappings.remove(&addr);
226:             }
227:         }
228: 
229:         self.vm_mappings.insert(vm_mapping);
230:     }
