221:         if let Some(next) = self.vm_mappings.find_next(&addr) {
222:             let (new_mapping, to_remove) = vm_mapping.try_merge_with(next);
223:             vm_mapping = new_mapping;
224:             if let Some(addr) = to_remove {
225:                 self.vm_mappings.remove(&addr);
226:             }
