240:     fn query(&self, range: &Range<Vaddr>) -> impl Iterator<Item = &VmMapping> {
241:         self.vm_mappings.find(range)
242:     }
243: 
244:     /// Calculates the total amount of overlap between `VmMapping`s
245:     /// and the provided range.
246:     fn count_overlap_size(&self, range: Range<Vaddr>) -> usize {
247:         let mut sum_overlap_size = 0;
248:         for vm_mapping in self.vm_mappings.find(&range) {
249:             let vm_mapping_range = vm_mapping.range();
250:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
251:             sum_overlap_size += intersected_range.end - intersected_range.start;
252:         }
253:         sum_overlap_size
254:     }
255: 
256:     /// Allocates a free region for mapping with a specific offset and size.
257:     ///
258:     /// If the provided range is already occupied, return an error.
259:     fn alloc_free_region_exact(&mut self, offset: Vaddr, size: usize) -> Result<Range<Vaddr>> {
260:         if self
261:             .vm_mappings
262:             .find(&(offset..offset + size))
263:             .next()
264:             .is_some()
265:         {
266:             return_errno_with_message!(
267:                 Errno::EEXIST,
268:                 "the range contains pages that are already mapped"
269:             );
270:         }
271: 
272:         Ok(offset..(offset + size))
273:     }
274: 
275:     /// Allocates a free region for mapping with a specific offset and size.
276:     ///
277:     /// If the provided range is already occupied, this function truncates all
278:     /// the mappings that intersect with the range.
279:     fn alloc_free_region_exact_truncate(
280:         &mut self,
281:         vm_space: &VmSpace,
282:         offset: Vaddr,
283:         size: usize,
284:         rss_delta: &mut RssDelta,
285:     ) -> Result<Range<Vaddr>> {
286:         let range = offset..offset + size;
287:         let mut mappings_to_remove = Vec::new();
288:         for vm_mapping in self.vm_mappings.find(&range) {
289:             mappings_to_remove.push(vm_mapping.map_to_addr());
290:         }
291: 
292:         for vm_mapping_addr in mappings_to_remove {
293:             let vm_mapping = self.remove(&vm_mapping_addr).unwrap();
294:             let vm_mapping_range = vm_mapping.range();
295:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
296: 
297:             let (left, taken, right) = vm_mapping.split_range(&intersected_range);
298:             if let Some(left) = left {
299:                 self.insert_without_try_merge(left);
300:             }
301:             if let Some(right) = right {
302:                 self.insert_without_try_merge(right);
303:             }
304: 
305:             rss_delta.add(taken.rss_type(), -(taken.unmap(vm_space) as isize));
306:         }
307: 
308:         Ok(offset..(offset + size))
309:     }
310: 
311:     /// Allocates a free region for mapping.
312:     ///
313:     /// If no such region is found, return an error.
314:     fn alloc_free_region(&mut self, size: usize, align: usize) -> Result<Range<Vaddr>> {
315:         // Fast path that there's still room to the end.
316:         let highest_occupied = self
317:             .vm_mappings
318:             .iter()
319:             .next_back()
320:             .map_or(VMAR_LOWEST_ADDR, |vm_mapping| vm_mapping.range().end);
321:         // FIXME: The up-align may overflow.
322:         let last_occupied_aligned = highest_occupied.align_up(align);
323:         if let Some(last) = last_occupied_aligned.checked_add(size)
324:             && last <= VMAR_CAP_ADDR
325:         {
326:             return Ok(last_occupied_aligned..last);
327:         }
328: 
329:         // Slow path that we need to search for a free region.
330:         // Here, we use a simple brute-force FIRST-FIT algorithm.

