292:         for vm_mapping_addr in mappings_to_remove {
293:             let vm_mapping = self.remove(&vm_mapping_addr).unwrap();
294:             let vm_mapping_range = vm_mapping.range();
295:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
