35:     /// range contains pages that are not mapped.
36:     pub fn is_fully_mapped(&self) -> bool {
37:         let mut last_mapping_end = self.range.start;
38: 
39:         for mapping in self.iter() {
40:             if last_mapping_end < mapping.map_to_addr() {
41:                 return false;
42:             }
