175:     /// Checks whether `addr..addr + size` is covered by a single `VmMapping`,
176:     /// and returns the address of the single `VmMapping` if successful.
177:     fn check_lies_in_single_mapping(&self, addr: Vaddr, size: usize) -> Result<Vaddr> {
178:         if let Some(vm_mapping) = self
179:             .vm_mappings
180:             .find_one(&addr)
181:             .filter(|vm_mapping| vm_mapping.map_end() - addr >= size)
182:         {
183:             Ok(vm_mapping.map_to_addr())
184:         } else {
185:             return_errno_with_message!(Errno::EFAULT, "the range must lie in a single mapping");
186:         }
187:     }
