373: fn map_vdso_to_vmar(vmar: &Vmar) -> Option<Vaddr> {
374:     use crate::vdso::{VDSO_VMO_LAYOUT, vdso_vmo};
375: 
376:     let vdso_vmo = vdso_vmo()?;
377: 
378:     let options = vmar
379:         .new_map(VDSO_VMO_LAYOUT.size, VmPerms::empty())
380:         .unwrap()
381:         .vmo(vdso_vmo);
382: 
383:     let vdso_vmo_base = options.build().unwrap();
384:     let vdso_data_base = vdso_vmo_base + VDSO_VMO_LAYOUT.data_segment_offset;
385:     let vdso_text_base = vdso_vmo_base + VDSO_VMO_LAYOUT.text_segment_offset;
386: 
387:     let data_perms = VmPerms::READ;
388:     let text_perms = VmPerms::READ | VmPerms::EXEC;
389:     vmar.protect(
390:         data_perms,
391:         vdso_data_base..(vdso_data_base + VDSO_VMO_LAYOUT.data_segment_size),
392:     )
393:     .unwrap();
394:     vmar.protect(
395:         text_perms,
396:         vdso_text_base..(vdso_text_base + VDSO_VMO_LAYOUT.text_segment_size),
397:     )
398:     .unwrap();
399:     Some(vdso_text_base)
400: }

