244:     /// Calculates the total amount of overlap between `VmMapping`s
245:     /// and the provided range.
246:     fn count_overlap_size(&self, range: Range<Vaddr>) -> usize {
247:         let mut sum_overlap_size = 0;
248:         for vm_mapping in self.vm_mappings.find(&range) {
249:             let vm_mapping_range = vm_mapping.range();
250:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
251:             sum_overlap_size += intersected_range.end - intersected_range.start;
