189:     /// Inserts a `VmMapping` into the `Vmar`, without attempting to merge with
190:     /// neighboring mappings.
191:     ///
192:     /// The caller must ensure that the given `VmMapping` is not mergeable with
193:     /// any neighboring mappings.
194:     ///
195:     /// Make sure the insertion doesn't exceed address space limit.
196:     fn insert_without_try_merge(&mut self, vm_mapping: VmMapping) {
197:         self.total_vm += vm_mapping.map_size();
