72: pub enum MadviseBehavior {
73:     MADV_NORMAL = 0,     /* no further special treatment */
74:     MADV_RANDOM = 1,     /* expect random page references */
75:     MADV_SEQUENTIAL = 2, /* expect sequential page references */
76:     MADV_WILLNEED = 3,   /* will need these pages */
77:     MADV_DONTNEED = 4,   /* don't need these pages */
78: 
79:     /* common parameters: try to keep these consistent across architectures */
80:     MADV_FREE = 8,           /* free pages only if memory pressure */
81:     MADV_REMOVE = 9,         /* remove these pages & resources */
82:     MADV_DONTFORK = 10,      /* don't inherit across fork */
83:     MADV_DOFORK = 11,        /* do inherit across fork */
84:     MADV_HWPOISON = 100,     /* poison a page for testing */
85:     MADV_SOFT_OFFLINE = 101, /* soft offline page for testing */
86: 
87:     MADV_MERGEABLE = 12,   /* KSM may merge identical pages */
88:     MADV_UNMERGEABLE = 13, /* KSM may not merge identical pages */
89: 
90:     MADV_HUGEPAGE = 14,   /* Worth backing with hugepages */
91:     MADV_NOHUGEPAGE = 15, /* Not worth backing with hugepages */
92: 
93:     MADV_DONTDUMP = 16, /* Explicitly exclude from the core dump,
94:                         overrides the coredump filter bits */
95:     MADV_DODUMP = 17, /* Clear the MADV_DONTDUMP flag */
96: 
97:     MADV_WIPEONFORK = 18, /* Zero memory on fork, child only */
98:     MADV_KEEPONFORK = 19, /* Undo MADV_WIPEONFORK */
99: 
100:     MADV_COLD = 20,    /* deactivate these pages */
101:     MADV_PAGEOUT = 21, /* reclaim these pages */
102: 
