63: impl From<VmPerms> for Rights {
64:     fn from(vm_perms: VmPerms) -> Rights {
65:         let mut rights = Rights::empty();
66:         if vm_perms.contains(VmPerms::READ) {
67:             rights |= Rights::READ;
68:         }
69:         if vm_perms.contains(VmPerms::WRITE) {
70:             rights |= Rights::WRITE;
71:         }
72:         if vm_perms.contains(VmPerms::EXEC) {
73:             rights |= Rights::EXEC;
74:         }
75:         rights
76:     }
77: }
78: 
79: impl From<PageFlags> for VmPerms {
80:     fn from(flags: PageFlags) -> Self {
81:         let mut perms = VmPerms::empty();
82:         if flags.contains(PageFlags::R) {
83:             perms |= VmPerms::READ;
84:         }
85:         if flags.contains(PageFlags::W) {
86:             perms |= VmPerms::WRITE;
87:         }
88:         if flags.contains(PageFlags::X) {
89:             perms |= VmPerms::EXEC;
90:         }
91:         perms
92:     }
