38:         let allowed = VmPerms::from_bits_truncate((*self & Self::ALL_MAY_PERMS).bits >> 3);
39:         if !allowed.contains(requested) {
40:             return_errno_with_message!(Errno::EACCES, "permission denied");
41:         }
