37:         let mut last_mapping_end = self.range.start;
38: 
39:         for mapping in self.iter() {
40:             if last_mapping_end < mapping.map_to_addr() {
41:                 return false;
42:             }
43:             last_mapping_end = mapping.map_end();
44:         }
45: 
46:         if last_mapping_end < self.range.end {
47:             return false;
48:         }
49: 
50:         true
51:     }
52: }

