+// SPDX-License-Identifier: MPL-2.0
+
+#include <sys/mman.h>
+
+#include "../test.h"
+
+static char *start_addr;
+
+#define PAGE_SIZE 4096
+
+FN_SETUP(init)
+{
+	start_addr = CHECK_WITH(mmap(NULL, PAGE_SIZE * 4, PROT_READ,
