57:     // If neither MS_SYNC nor MS_ASYNC is specified, Linux defaults to MS_ASYNC behavior.
58:     if flags.contains(MsyncFlags::MS_SYNC) {
59:         task_fn();
60:     } else {
61:         ThreadOptions::new(task_fn).spawn();
