235:             start,
236:             end,
237:             read_char,
238:             write_char,
239:             exec_char,
240:             shared_char,
241:             offset,
242:             dev_major,
243:             dev_minor,
244:             ino,
245:             name
246:         )?;
247: 
248:         Ok(())
