707: /// Memory mapped by a [`VmMapping`].
708: #[derive(Debug)]
709: pub(super) enum MappedMemory {
710:     /// Anonymous memory.
711:     ///
712:     /// These pages are not associated with any files. On-demand population is possible by enabling
