259: /****************************** Page faults **********************************/
260: 
261: impl VmMapping {
262:     /// Handles a page fault.
263:     pub(super) fn handle_page_fault(
264:         &self,
265:         vm_space: &VmSpace,
266:         page_fault_info: &PageFaultInfo,
267:         rss_delta: &mut RssDelta,
268:     ) -> Result<()> {
269:         if !self.perms.contains(page_fault_info.required_perms) {
270:             trace!(
271:                 "self.perms {:?}, page_fault_info.required_perms {:?}, self.range {:?}",
272:                 self.perms,
273:                 page_fault_info.required_perms,
274:                 self.range()
275:             );
276:             return_errno_with_message!(Errno::EACCES, "perm check fails");
277:         }
278: 
279:         let page_aligned_addr = page_fault_info.address.align_down(PAGE_SIZE);
280:         let is_write = page_fault_info.required_perms.contains(VmPerms::WRITE);
281: 
282:         if !is_write
283:             && matches!(&self.mapped_mem, MappedMemory::Vmo(_))
284:             && self.handle_page_faults_around
285:         {
286:             let res = self.handle_page_faults_around(
287:                 vm_space,
288:                 page_aligned_addr,
289:                 page_fault_info.required_perms,
290:                 rss_delta,
291:             );
292: 
293:             // Errors caused by the "around" pages should be ignored, so here we
294:             // only return the error if the faulting page is still not mapped.
295:             if res.is_err() {
296:                 let preempt_guard = disable_preempt();
297:                 let mut cursor = vm_space.cursor(
298:                     &preempt_guard,
299:                     &(page_aligned_addr..page_aligned_addr + PAGE_SIZE),
300:                 )?;
301:                 if let (_, Some(_)) = cursor.query().unwrap() {
302:                     return Ok(());
303:                 }
304:             }
305: 
306:             return res;
307:         }
308: 
309:         self.handle_single_page_fault(
310:             vm_space,
311:             page_aligned_addr,
312:             page_fault_info.required_perms,
313:             rss_delta,
314:         )
315:     }
316: 
317:     fn handle_single_page_fault(
318:         &self,
319:         vm_space: &VmSpace,
320:         page_aligned_addr: Vaddr,
321:         required_perms: VmPerms,
322:         rss_delta: &mut RssDelta,
323:     ) -> Result<()> {
324:         'retry: loop {
325:             let preempt_guard = disable_preempt();
326:             let mut cursor = vm_space.cursor_mut(
327:                 &preempt_guard,
328:                 &(page_aligned_addr..page_aligned_addr + PAGE_SIZE),
329:             )?;
330: 
331:             let (va, item) = cursor.query().unwrap();
332:             let is_write = required_perms.contains(VmPerms::WRITE);
333:             match item {
334:                 Some(VmQueriedItem::MappedRam { frame, mut prop }) => {
335:                     if VmPerms::from(prop.flags).contains(required_perms) {
336:                         // The page fault is already handled maybe by other threads.
337:                         // Just flush the TLB and return.
338:                         TlbFlushOp::for_range(va).perform_on_current();
339:                         return Ok(());
340:                     }
341:                     assert!(is_write);
342:                     // Perform COW if it is a write access to a shared mapping.
343: 
344:                     // Skip if the page fault is already handled.
345:                     if prop.flags.contains(PageFlags::W) {
346:                         return Ok(());
347:                     }
348: 
349:                     // If the forked child or parent immediately unmaps the page after
350:                     // the fork without accessing it, we are the only reference to the
351:                     // frame. We can directly map the frame as writable without
352:                     // copying. In this case, the reference count of the frame is 2 (
353:                     // one for the mapping and one for the frame handle itself).
354:                     let only_reference = frame.reference_count() == 2;
355: 
356:                     let new_flags = PageFlags::W | PageFlags::ACCESSED | PageFlags::DIRTY;
357: 
358:                     if self.is_shared || only_reference {
359:                         cursor.protect_next(PAGE_SIZE, |flags, _cache| {
360:                             *flags |= new_flags;
361:                         });
362:                         cursor.flusher().issue_tlb_flush(TlbFlushOp::for_range(va));
363:                         cursor.flusher().dispatch_tlb_flush();
364:                     } else {
365:                         let new_frame = duplicate_frame(&frame)?;
366:                         prop.flags |= new_flags;
367:                         cursor.map(new_frame.into(), prop);
368:                         rss_delta.add(self.rss_type(), 1);
369:                     }
370:                     cursor.flusher().sync_tlb_flush();
371:                 }
372:                 Some(VmQueriedItem::MappedIoMem { .. }) => {
373:                     // The page of I/O memory is populated when the memory
374:                     // mapping is created.
375:                     return_errno_with_message!(
376:                         Errno::EFAULT,
377:                         "device memory page faults cannot be resolved"
378:                     );
379:                 }
380:                 None => {
381:                     // Map a new frame to the page fault address.
382:                     let (frame, is_readonly) = match self.prepare_page(page_aligned_addr, is_write)
383:                     {
384:                         Ok((frame, is_readonly)) => (frame, is_readonly),
385:                         Err(VmoCommitError::Err(e)) => return Err(e),
386:                         Err(VmoCommitError::NeedIo(index)) => {
387:                             drop(cursor);
388:                             drop(preempt_guard);
389:                             self.vmo().unwrap().commit_on(index, CommitFlags::empty())?;
390:                             continue 'retry;
391:                         }
392:                     };
393: 
394:                     let vm_perms = {
395:                         let mut perms = self.perms;
396:                         if is_readonly {
397:                             // COW pages are forced to be read-only.
398:                             perms -= VmPerms::WRITE;
399:                         }
400:                         perms
401:                     };
402: 
403:                     let mut page_flags = vm_perms.into();
404:                     page_flags |= PageFlags::ACCESSED;
405:                     if is_write {
406:                         page_flags |= PageFlags::DIRTY;
407:                     }
408:                     let map_prop = PageProperty::new_user(page_flags, CachePolicy::Writeback);
409: 
410:                     cursor.map(frame, map_prop);
411:                     rss_delta.add(self.rss_type(), 1);
412:                 }
413:             }
414:             break 'retry;
415:         }
416: 
417:         Ok(())
418:     }
419: 
420:     fn prepare_page(
421:         &self,
422:         page_aligned_addr: Vaddr,
423:         write: bool,
424:     ) -> core::result::Result<(UFrame, bool), VmoCommitError> {
425:         let mut is_readonly = false;
426: 
427:         let vmo = match &self.mapped_mem {
428:             MappedMemory::Vmo(vmo) => vmo,
429:             MappedMemory::Anonymous => {
430:                 // Anonymous mapping. Allocate a new frame.
431:                 return Ok((FrameAllocOptions::new().alloc_frame()?.into(), is_readonly));
432:             }
433:             MappedMemory::Device => {
434:                 // Device memory is populated when the memory mapping is created.
435:                 return Err(VmoCommitError::Err(Error::with_message(
436:                     Errno::EFAULT,
437:                     "device memory page faults cannot be resolved",
438:                 )));
439:             }
440:         };
441: 
442:         let page_offset = page_aligned_addr - self.map_to_addr;
443:         if !self.is_shared && page_offset >= vmo.valid_size() {
444:             // The page index is outside the VMO. This is only allowed in private mapping.
445:             return Ok((FrameAllocOptions::new().alloc_frame()?.into(), is_readonly));
446:         }
447: 
448:         let page = vmo.get_committed_frame(page_offset)?;
449:         if !self.is_shared && write {
450:             // Write access to private VMO-backed mapping. Performs COW directly.
451:             Ok((duplicate_frame(&page)?.into(), is_readonly))
452:         } else {
453:             // Operations to shared mapping or read access to private VMO-backed mapping.
454:             // If read access to private VMO-backed mapping triggers a page fault,
455:             // the map should be readonly. If user next tries to write to the frame,
456:             // another page fault will be triggered which will performs a COW (Copy-On-Write).
457:             is_readonly = !self.is_shared;
458:             Ok((page, is_readonly))
459:         }
460:     }
461: 
462:     /// Handles a page fault and maps additional surrounding pages.
463:     fn handle_page_faults_around(
464:         &self,
465:         vm_space: &VmSpace,
466:         page_aligned_addr: Vaddr,
467:         required_perms: VmPerms,
468:         mut rss_delta: &mut RssDelta,
469:     ) -> Result<()> {
470:         const SURROUNDING_PAGE_NUM: usize = 16;
471:         const SURROUNDING_PAGE_ADDR_MASK: usize = !(SURROUNDING_PAGE_NUM * PAGE_SIZE - 1);
472: 
473:         let vmo = self.vmo().unwrap();
474:         let around_page_addr = page_aligned_addr & SURROUNDING_PAGE_ADDR_MASK;
475:         let size = min(vmo.valid_size(), self.map_size.get());
476:         let mut start_addr = max(around_page_addr, self.map_to_addr);
477:         let end_addr = min(
478:             start_addr + SURROUNDING_PAGE_NUM * PAGE_SIZE,
479:             self.map_to_addr + size,
480:         );
481: 
482:         // The page fault address falls outside the VMO bounds.
483:         // Only a single page fault is handled in this situation.
484:         if end_addr <= page_aligned_addr {
485:             return self.handle_single_page_fault(
486:                 vm_space,
487:                 page_aligned_addr,
488:                 required_perms,
489:                 rss_delta,
490:             );
491:         }
492: 
493:         let vm_perms = self.perms - VmPerms::WRITE;
494: 
495:         'retry: loop {
496:             let preempt_guard = disable_preempt();
497:             let mut cursor = vm_space.cursor_mut(&preempt_guard, &(start_addr..end_addr))?;
498: 
499:             let rss_delta_ref = &mut rss_delta;
500:             let operate =
501:                 move |commit_fn: &mut dyn FnMut()
502:                     -> core::result::Result<UFrame, VmoCommitError>| {
503:                     if let (_, None) = cursor.query().unwrap() {
504:                         // We regard all the surrounding pages as accessed, no matter
505:                         // if it is really so. Then the hardware won't bother to update
506:                         // the accessed bit of the page table on following accesses.
507:                         let page_flags = PageFlags::from(vm_perms) | PageFlags::ACCESSED;
508:                         let page_prop = PageProperty::new_user(page_flags, CachePolicy::Writeback);
509:                         let frame = commit_fn()?;
510:                         cursor.map(frame, page_prop);
511:                         rss_delta_ref.add(self.rss_type(), 1);
512:                     } else {
513:                         let next_addr = cursor.virt_addr() + PAGE_SIZE;
514:                         if next_addr < end_addr {
515:                             let _ = cursor.jump(next_addr);
516:                         }
517:                     }
518:                     Ok(())
519:                 };
520:

520: 
521:             let start_offset = start_addr - self.map_to_addr;
522:             let end_offset = end_addr - self.map_to_addr;
523:             match vmo.try_operate_on_range(&(start_offset..end_offset), operate) {
524:                 Ok(_) => return Ok(()),
525:                 Err(VmoCommitError::NeedIo(index)) => {
526:                     drop(preempt_guard);
527:                     vmo.commit_on(index, CommitFlags::empty())?;
528:                     start_addr = (index * PAGE_SIZE - vmo.offset()) + self.map_to_addr;
529:                     continue 'retry;
530:                 }
531:                 Err(VmoCommitError::Err(e)) => return Err(e),
532:             }
533:         }
534:     }
535: }
